class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        if len(s) < k:
            return 0
        from collections import Counter
        counts = Counter(s)
        for c in counts:
            if counts[c] < k:
                return max(self.longestSubstring(sub, k) for sub in s.split(c))
        return len(s)

